  .thumb{width:315px;height:188px;object-fit:cover;margin-right:16px}
  .session-info{padding-top:0;flex:1}
  .session-title{color:#08746e;font-size:29px;font-weight:bold;line-height:1.1;display:inline-block}
  .activity{display:inline-block;background:#e5e7e9;color:#777;font-weight:bold;font-size:14px;padding:8px 11px;margin-left:14px;vertical-align:5px}
  .session-sub{color:#08746e;font-weight:bold;font-size:21px;margin-top:5px}
  .date{font-size:14px;font-weight:bold;color:#555;margin:10px 0}
  .desc{font-size:16px;line-height:1.22;max-width:690px}
  .custom-board{width:315px;height:188px;margin-right:16px;background:#8a6b3f;border-radius:12px;padding:15px;box-shadow:inset 0 0 0 4px #ad8b55;display:flex;align-items:center;justify-content:center}
  .board-inner{background:#292b2d;color:#fff;width:100%;height:100%;border:4px solid #151515;text-align:center;padding:18px 8px;font-size:21px;font-style:italic;line-height:1.45}
  .board-inner b{display:block;font-style:normal;font-size:17px;margin-bottom:10px}
  .reference{display:flex;gap:35px}
  .reference-main{width:625px}
  .reference-main h1{font-size:32px;margin:0 0 45px}
  .reference-main h2{font-size:20px;margin:0 0 16px}
  .reference-main h3{font-size:19px;margin:12px 0 2px}
  .reference-main p{margin:0 0 15px;line-height:1.18}
  .side{width:315px}
  .sidebox{background:#dedfe1;margin-bottom:16px;padding:17px 15px;color:#08746e;font-weight:bold;font-size:16px;min-height:53px}
  .sidebox strong{display:block;color:#333;font-size:19px;margin-bottom:23px}
  .download{background:#f0f0f0;color:#08746e;min-height:70px;padding:15px;font-size:16px}
  .download:before{content:"⇩";font-size:44px;float:left;margin-right:14px;color:#63c7bb}
  .vocab h1{margin-bottom:45px}
  .vocab h2{font-size:20px;margin-bottom:14px}
  .vocab-item{margin:0 0 14px;line-height:1.12}
  .vocab-item b{display:block}
  .practice{display:inline-block;background:#62c8bd;color:#003b4b;font-weight:bold;font-size:25px;padding:12px 15px;margin-top:3px}
  footer{margin-top:80px}
  .footer-top{background:#f1f1f1;min-height:223px;padding:38px 0}
  .footer-inner{width:992px;margin:auto;display:flex;position:relative}
  .footer-col{width:325px}
  .footer-col h2{margin:0 0 8px;font-size:24px}
  .footer-col a{display:block;color:#17665f;font-weight:bold;line-height:1.45}
  .footer-links{position:absolute;right:0;top:0;color:#17665f;font-weight:bold;line-height:2}
  .footer-bottom{background:#4d4d4d;color:white;min-height:275px;padding:26px 0}
  .bottom-inner{width:992px;margin:auto}
  .bottom-inner h2{font-size:23px;margin:0 0 25px}
  .explore{display:grid;grid-template-columns:repeat(6,1fr);border-bottom:1px solid #888;padding-bottom:19px;margin-bottom:20px}
  .explore span{font-weight:bold;font-size:14px;border-right:1px solid #999;padding:0 20px}
  .explore span:first-child{padding-left:0}
  .legal{font-size:13px;line-height:2}
  @media(max-width:1000px){
    .top-inner,.hero-inner,.unit-head-inner,.selector-inner,.content,.footer-inner,.bottom-inner{width:94%}
    .main-nav{gap:12px}.session{flex-direction:column}.thumb,.custom-board{margin-bottom:15px}.reference{flex-direction:column}.side{width:100%}
  }
</style>
</head>
<body>
<header>
  <div class="topbar">
    <div class="top-inner">
      <div class="bbc"><span>B</span><span>B</span><span>C</span></div>
      <div class="signin"><i></i>Sign in</div>
      <div class="main-nav">
        <span>Home</span><span>News</span><span>Sport</span><span>Business</span><span>Innovation</span><span>Culture</span><span>Travel</span><span>•••</span>
        <span class="search-top">⌕&nbsp; Search BBC</span>
      </div>
    </div>
  </div>
  <div class="hero">
    <div class="hero-inner">
      <img class="brand" src="__PLACEHOLDER_ASSETS_BASE_DIR__/015.png" width="430" height="76" alt="Learning English">
      <button class="language btn">ENGLISH CHANGE LANGUAGE</button>
    </div>
  </div>
  <nav class="course-nav">
    <div class="course-inner">
      <span>Courses <small class="down">▼</small></span>
      <span>Grammar <small class="down">▼</small></span>
      <span>Pronunciation <small class="down">▼</small></span>
      <span>Vocabulary <small class="down">▼</small></span>
      <span>News <small class="down">▼</small></span>
      <span>More... <small class="down">▼</small></span>
      <span class="course-search">⌕&nbsp; Search <small>▼</small></span>
    </div>
  </nav>
</header>

<section class="unit-head">
  <div class="unit-head-inner">
    <div class="unit-number" id="unitNumber">1</div>
    <div class="unit-title">
      <strong id="unitTitle">Unit 1: Towards advanced</strong><br>
      <span id="unitSubtitle">Welcome to our new course</span>
    </div>
    <button class="close-unit btn">Close unit selector</button>
  </div>
</section>

<section class="selector">
  <div class="selector-inner">
    <div class="select-label">SELECT A UNIT</div>
    <div class="units" id="units"></div>
    <div class="unit-numbers" id="unitNumbers"></div>
    <div class="tabs">
      <button class="tab active btn" data-tab="sessions">Sessions</button>
      <button class="tab btn" data-tab="vocabulary">Vocabulary reference</button>
      <button class="tab btn" data-tab="grammar">Grammar reference</button>
    </div>
  </div>
</section>

<main class="content" id="content"></main>

<footer>
  <div class="footer-top">
    <div class="footer-inner">
      <div class="footer-col">
        <h2>About</h2>
        <a>About BBC Learning English</a><a>Courses</a><a>Course site maps</a><a>Learning FAQ</a><a>Contact BBC Learning English</a>
      </div>
      <div class="footer-col">
        <h2>Social</h2>
        <a>TikTok</a><a>YouTube</a><a>Instagram</a><a>Facebook</a><a>Social media house rules</a>
      </div>
      <div class="footer-links">⌃ &nbsp; Back to top<br>◔ &nbsp; RSS</div>
    </div>
  </div>
  <div class="footer-bottom">
    <div class="bottom-inner">
      <h2>Explore the BBC</h2>
      <div class="explore">
        <span>Home<br><br>Travel</span><span>News<br><br>Earth</span><span>Sport<br><br>Video</span><span>Business<br><br>Live</span><span>Innovation</span><span>Culture</span>
      </div>
      <div class="legal">Terms of Use　 About the BBC　 Privacy Policy　 Cookies　 Accessibility Help　 Parental Guidance　 Contact the BBC　 BBC emails for you<br>
      Advertise with us<br>
      Copyright © 2025 BBC. The BBC is not responsible for the content of external sites. Read about our approach to external linking.</div>
    </div>
  </div>
</footer>

<script>
const data={
  1:{
    subtitle:"Welcome to our new course",
    sessions:[
      {img:"010.jpg",title:"BBC Masterclass",date:"04 JUL 2016",text:"Non-defining relative clauses are a speaker's friend. Dan teaches us five ways to use them in this bite-sized video.",board:"Non-defining relative clauses"},
      {img:"013.jpg",title:"News Review",date:"05 JUL 2016",text:"NASA's Juno mission has arrived at Jupiter. Find out more with Neil and Sian as they look at how the world's media is reacting and the words you need to talk about the story."}
    ]
  },
  4:{
    subtitle:"Grammar, news, vocabulary and pronunciation",
    sessions:[
      {title:"BBC Masterclass",date:"25 JUL 2016",text:"Dan uses linking words of contrast to destroy four myths about English people.",board:"Linking words of contrast"},
      {img:"019.png",title:"News Review",date:"26 JUL 2016",text:"Can chickens stop you getting bitten by mosquitoes? Join Rob and Sian in News Review as they bring you this exciting story and the language you need to understand it."}
    ]
  },
  7:{
    subtitle:"Grammar, news, vocabulary and pronunciation",
    sessions:[
      {title:"BBC Masterclass",date:"15 AUG 2016",text:"They say you shouldn't mix your drinks, but should you mix your conditionals? Find out in this Masterclass with Dan.",board:"Mixed conditionals"},
      {img:"020.png",title:"News Review",date:"16 AUG 2016",text:"Brazil has won a gold medal in athletics in a shocking pole vault final. Join Sian and Neil in News Review as they bring you this exciting story and the language you need to understand it."}
    ]
  }
};
let currentUnit=1,currentTab="sessions";
const units=document.getElementById("units"), nums=document.getElementById("unitNumbers");
for(let i=1;i<=30;i++){
  const b=document.createElement("button");b.className="unit-box btn"+(i===1?" active":"");b.dataset.unit=i;b.onclick=()=>selectUnit(i);units.appendChild(b);
  const n=document.createElement("span");n.textContent=i;nums.appendChild(n);
}
function selectUnit(n){
  currentUnit=n;
  document.querySelectorAll(".unit-box").forEach(x=>x.classList.toggle("active",+x.dataset.unit===n));
  document.getElementById("unitNumber").textContent=n;
  document.getElementById("unitTitle").textContent="Unit "+n+": Towards advanced";
  document.getElementById("unitSubtitle").textContent=data[n]?.subtitle||"Grammar, news, vocabulary and pronunciation";
  render();
}
function board(text){
  return `<div class="custom-board"><div class="board-inner"><b>BBC MASTERCLASS</b>${text}</div></div>`;
}
function renderSessions(){
  const d=data[currentUnit]||data[7];
  return d.sessions.map((s,i)=>`<article class="session btn">
    ${s.img?`<img class="thumb" src="__PLACEHOLDER_ASSETS_BASE_DIR__/${s.img}" width="315" height="188" alt="">`:board(s.board)}
    <div class="session-info">
      <span class="session-title">Session ${i+1}</span><span class="activity">1 ACTIVITY</span>
      <div class="session-sub">${s.title}</div><div class="date">${s.date}</div><div class="desc">${s.text}</div>
    </div>
  </article>`).join("");
}
function side(kind){
 return `<aside class="side"><div class="sidebox">View sessions in this unit&nbsp; <b>›</b></div>
 <div class="sidebox"><strong>Session ${kind}</strong>Practise this ${kind.toLowerCase()} &nbsp;›</div>
 <div class="download">DOWNLOAD CENTRE<br><b>Latest course content</b></div></aside>`;
}
function renderGrammar(){
 return `<div class="reference"><div class="reference-main">
 <h1>Grammar Reference</h1><h2>Conditionals review</h2><h3>Meaning and use</h3>
 <p>Conditional sentences express a connection between two actions or states. One thing happens because of another. These connections can be general, specific, likely, unlikely, real or imagined.</p>
 <p>Although there are quite a few different ways of forming conditional sentences there are common patterns known as zero, first, second and third conditionals.</p>
 <h3>Zero conditionals</h3><p>Used to refer to general truths, scientific facts and the predictable results of particular actions. One thing happens and because of this something else happens. In zero conditionals <i>if</i> and <i>when</i> have the same meaning.</p>
 <p><i>If you heat water enough, it boils.</i></p></div>${side("Session Vocabulary")}</div>`;
}
function renderVocab(){
 return `<div class="reference"><div class="reference-main vocab"><h1>Vocabulary Reference</h1>
 <h2>Session 2 - News Review</h2>
 ${[
 ["an upset","when someone beats the team or player that was expected to win"],
 ["pull something off","to succeed in doing something that is difficult"],
 ["egg somebody on","encourage someone or urge someone to do something (especially something they shouldn't do)"],
 ["pandemonium","a situation in which there is a lot of noise or craziness because people are excited, angry, or frightened"]
 ].map(x=>`<div class="vocab-item"><b>${x[0]}</b>${x[1]}</div>`).join("")}
 <h2>Session 3 - Lingohack</h2>
 ${[["medal tally","number of medals won"],["feeds on","eats, consumes (especially for animals)"],["cheating","breaking the rules of a competition"]].map(x=>`<div class="vocab-item"><b>${x[0]}</b>${x[1]}</div>`).join("")}
 <h2>Session 4 - Pygmalion: 8 uses of 'round'</h2>
 ${[["driving him around the bend (C2)","making him very annoyed"],["comes round (C2)","begins to accept something previously rejected"],["round and round (B2)","moving in a circular direction"],["round the clock (C1)","all day and all night"],["round (A2)","on all sides (of something)"],["goes round to (A2)","visits"],["in a roundabout kind of way (C2)","more or less; sort of"],["round off (B2)","finish; complete (something)"]].map(x=>`<div class="vocab-item"><b>${x[0]}</b>${x[1]}</div>`).join("")}
 <button class="practice btn">Practise Vocabulary&nbsp; ›</button></div>${side("Session Grammar")}</div>`;
}
function render(){
 document.getElementById("content").innerHTML=currentTab==="sessions"?renderSessions():currentTab==="grammar"?renderGrammar():renderVocab();
 document.querySelectorAll(".tab").forEach(t=>t.classList.toggle("active",t.dataset.tab===currentTab));
}
document.querySelectorAll(".tab").forEach(t=>t.onclick=()=>{currentTab=t.dataset.tab;render()});
render();
</script>
</body>
</html>
